# owner: platform
"""Plain text contact sheet for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def contact_sheet(students: Iterable[Student]) -> str:
    """Rows of name, section and email, sorted by name."""
    roster = sorted(students, key=_name_key)
    if not roster:
        raise ValueError("no students given")
    _require_emails(roster)
    return "\n".join(_align(roster))

def _name_key(student: Student) -> str:
    return student.display_name.casefold()

def _require_emails(roster: List[Student]) -> None:
    for student in roster:
        if not student.email:
            raise ValueError(
                f"no email for {student.display_name}"
            )

def _widths(roster: List[Student]) -> Tuple[int, int]:
    names = [student.display_name for student in roster]
    sections = [student.section for student in roster]
    return max(map(len, names)), max(map(len, sections))

def _align(roster: List[Student]) -> List[str]:
    widths = _widths(roster)
    return [_row(student, widths) for student in roster]

def _row(student: Student, widths: Tuple[int, int]) -> str:
    name_width, section_width = widths
    cells = [
        student.display_name.ljust(name_width),
        student.section.ljust(section_width),
        student.email
    ]
    return "  ".join(cells)

