# owner: platform
import unittest

from rosterkit.contacts import contact_sheet
from rosterkit.models import Student

# ---
def make_student(last_name, first_name, section, email):
    return Student(
        "1", last_name, first_name, section, email
    )

class ContactSheetTests(unittest.TestCase):
    def test_rows_sorted_by_name_with_aligned_columns(self):
        students = [
            make_student(
                "Varrow", "Ines", "AB", "ines@school.edu"
            ),
            make_student(
                "Thistle", "Bram", "B", "bram@school.edu"
            )
        ]
        self.assertEqual(
            contact_sheet(students),
            "Thistle, Bram  B   bram@school.edu\n"
            "Varrow, Ines   AB  ines@school.edu"
        )

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Ruiz", "Sefa", "A", None)
        ]
        with self.assertRaisesRegex(ValueError, "Ruiz"):
            contact_sheet(students)

    def test_blank_email_counts_as_missing(self):
        students = [
            make_student("Ruiz", "Sefa", "A", "")
        ]
        with self.assertRaisesRegex(ValueError, "Ruiz"):
            contact_sheet(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_sheet([])
